<script setup>
import {onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {createRound,getRounds,getSeason,getStandings,initStandings,updateRound,updateRoundStatus,updateSeasonRecord} from '../../api/league'
const route=useRoute(),router=useRouter(),seasonId=Number(route.params.id),season=ref({}),rounds=ref([]),standings=ref([]),loading=ref(false)
const roundVisible=ref(false),recordVisible=ref(false),roundId=ref(null),recordId=ref(null),roundRef=ref(),recordRef=ref()
const blankRound=()=>({roundNo:1,roundName:'',startDate:'',endDate:''}),round=reactive(blankRound())
const blankRecord=()=>({wins:0,draws:0,losses:0,goalsFor:0,goalsAgainst:0}),record=reactive(blankRecord())
const roundRules={roundNo:[{required:true,type:'number',min:1,message:'轮次必须大于0'}],roundName:[{required:true,message:'请输入轮次名称'}],startDate:[{required:true,message:'请选择开始日期'}],endDate:[{required:true,message:'请选择结束日期'}]}
const nonnegative={type:'number',min:0,message:'不能小于0'},recordRules={wins:[nonnegative],draws:[nonnegative],losses:[nonnegative],goalsFor:[nonnegative],goalsAgainst:[nonnegative]}
const load=async()=>{loading.value=true;try{const [s,r,t]=await Promise.all([getSeason(seasonId),getRounds(seasonId),getStandings(seasonId)]);season.value=s.data;rounds.value=r.data;standings.value=t.data}finally{loading.value=false}}
const openRound=row=>{roundId.value=row?.roundId||null;Object.assign(round,blankRound(),row||{});roundVisible.value=true}
const saveRound=async()=>{await roundRef.value.validate();if(round.endDate<round.startDate)return ElMessage.error('结束日期不能早于开始日期');roundId.value?await updateRound(roundId.value,round):await createRound(seasonId,round);roundVisible.value=false;ElMessage.success('轮次已保存');await load()}
const advance=async row=>{const next={DRAFT:'PUBLISHED',PUBLISHED:'FINISHED'}[row.roundStatus];if(!next)return;await updateRoundStatus(row.roundId,next);ElMessage.success('状态已更新');await load()}
const initialize=async()=>{const r=await initStandings(seasonId);ElMessage.success(r.data?`新增${r.data}条记录`:'记录已完整，无需重复初始化');await load()}
const openRecord=row=>{recordId.value=row.recordId;Object.assign(record,blankRecord(),row);recordVisible.value=true}
const saveRecord=async()=>{await recordRef.value.validate();await updateSeasonRecord(recordId.value,record);recordVisible.value=false;ElMessage.success('测试战绩已更新');await load()}
onMounted(load)
</script>
<template><div v-loading="loading"><el-page-header @back="router.push('/admin/seasons')"><template #content>{{season.seasonName||'赛季详情'}}</template></el-page-header><el-tabs class="tabs"><el-tab-pane label="轮次管理"><div class="actions"><el-button type="primary" @click="openRound()">新增轮次</el-button></div><el-table :data="rounds"><el-table-column prop="roundNo" label="编号"/><el-table-column prop="roundName" label="名称"/><el-table-column prop="startDate" label="开始"/><el-table-column prop="endDate" label="结束"/><el-table-column prop="roundStatus" label="状态"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="openRound(row)">编辑</el-button><el-button v-if="row.roundStatus!=='FINISHED'" link type="success" @click="advance(row)">{{row.roundStatus==='DRAFT'?'发布':'结束'}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="积分榜管理"><el-alert title="当前为比赛模块完成前的管理员手工测试战绩维护。" type="warning" :closable="false"/><div class="actions"><el-button type="primary" @click="initialize">初始化ACTIVE俱乐部</el-button></div><el-table :data="standings"><el-table-column prop="rank" label="排名"/><el-table-column prop="clubName" label="俱乐部" min-width="160"/><el-table-column prop="matchesPlayed" label="场"/><el-table-column prop="wins" label="胜"/><el-table-column prop="draws" label="平"/><el-table-column prop="losses" label="负"/><el-table-column prop="goalDifference" label="净胜"/><el-table-column prop="points" label="积分"/><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="openRecord(row)">维护</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></div><el-dialog v-model="roundVisible" :title="roundId?'编辑轮次':'新增轮次'" width="520px"><el-form ref="roundRef" :model="round" :rules="roundRules" label-width="90px"><el-form-item label="轮次编号" prop="roundNo"><el-input-number v-model="round.roundNo" :min="1"/></el-form-item><el-form-item label="名称" prop="roundName"><el-input v-model="round.roundName"/></el-form-item><el-form-item label="开始日期" prop="startDate"><el-date-picker v-model="round.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期" prop="endDate"><el-date-picker v-model="round.endDate" value-format="YYYY-MM-DD"/></el-form-item></el-form><template #footer><el-button @click="roundVisible=false">取消</el-button><el-button type="primary" @click="saveRound">保存</el-button></template></el-dialog><el-dialog v-model="recordVisible" title="维护测试战绩" width="500px"><el-form ref="recordRef" :model="record" :rules="recordRules" label-width="80px"><el-form-item label="胜" prop="wins"><el-input-number v-model="record.wins" :min="0"/></el-form-item><el-form-item label="平" prop="draws"><el-input-number v-model="record.draws" :min="0"/></el-form-item><el-form-item label="负" prop="losses"><el-input-number v-model="record.losses" :min="0"/></el-form-item><el-form-item label="进球" prop="goalsFor"><el-input-number v-model="record.goalsFor" :min="0"/></el-form-item><el-form-item label="失球" prop="goalsAgainst"><el-input-number v-model="record.goalsAgainst" :min="0"/></el-form-item></el-form><template #footer><el-button @click="recordVisible=false">取消</el-button><el-button type="primary" @click="saveRecord">保存</el-button></template></el-dialog></template>
<style scoped>.tabs{margin-top:20px}.actions{display:flex;justify-content:flex-end;margin:12px 0}</style>
